head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.hideDebugCtrls();
        scwin.resizeToWin();
        scwin.getParam();
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30005.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    await scwin.listDsclForReg();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Discls_OnLoadCompleted
 * @description dts_Discls 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Discls_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30005.dts_Discls_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Discls_OnDblClick
 * @description grd_Discls 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Discls_OnDblClick = async function(row, colid) {
    try {
        await scwin.setAcpt_No(grd_Discls, row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30005.grd_Discls_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30005.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listDsclForReg
 * @description list Dscl For Reg 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listDsclForReg = async function() {
    // var MARKET_FLAG = getObjectValue(rdo_Tab1_Market_Flag);
    url += "&SEARCH_TYP=N";
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&SCREN_ID=" + 'ULDSTF30005.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Discls",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "dts_Discls=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParam
 * @description get Param 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function() {
    const vTemp = frame.FrameID;
    const Temp2 = vTemp.split("|")[1];
    const vISUR_CD = Temp2.split("=")[1];
    txb_ISUR_CD.setValue(vISUR_CD);
};

/**
 * @method
 * @name resizeToWin
 * @description resize To Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.resizeToWin = function() {
    frame.Width = 480;
    frame.Height = 530;
};

/**
 * @method
 * @name hideDebugCtrls
 * @description 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    // 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
    panel_debug.hide();
};

/**
 * @method
 * @name setAcpt_No
 * @description set Acpt No 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {String} ColID ColID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setAcpt_No = async function(GridID, row, ColID) {
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    const vFORM_CD = objDataID.getCellData(row, "ACPT_NO");
    const vFORM_KOR_NM = objDataID.getCellData(row, "DISCLS_TITLE");
    const vDISCLS_PUBL_DDTM = objDataID.getCellData(row, "DISCLS_PUBL_DDTM");
    const parentWin = $c.frame.path("../");
    parentWin.txb_ACPT_NO.setValue(vFORM_CD);
    parentWin.txb_RptNm.setValue(vFORM_KOR_NM);
    if (parentWin.edt_DISCLS_PUBL_DDTM !== null) {
        parentWin.edt_DISCLS_PUBL_DDTM.setValue(vDISCLS_PUBL_DDTM);
    } else {
        // 메모일정 사용
        parentWin.txb_DISCLS_PUBL_DDTM.setValue(vDISCLS_PUBL_DDTM);
    }
    // 여러일정등록화면 관리기간 시작일 입력 위해 추가 2020.09.04
    if (parentWin.edt_SDate !== null) {
        parentWin.edt_SDate.setValue(vDISCLS_PUBL_DDTM);
    }
    await $c.win.closePopup();
};
